"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

_DIRECTIVE = "@include"


def _include_target(line):
    parts = line.strip().split(None, 1)
    if parts and parts[0] == _DIRECTIVE:
        if len(parts) < 2 or not parts[1].strip():
            raise ConfigError("@include requires a path")
        return parts[1].strip()
    return None


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(path, lines, stack):
    base = os.path.dirname(os.path.abspath(path))
    out = []
    for line in lines:
        target = _include_target(line)
        if target is None:
            out.append(line)
            continue
        inc_path = os.path.normpath(os.path.join(base, target))
        real = os.path.realpath(inc_path)
        if real in stack:
            raise ConfigError("include cycle detected: {}".format(inc_path))
        if not os.path.isfile(inc_path):
            raise ConfigError("included file not found: {}".format(inc_path))
        try:
            inc_lines = _read_lines(inc_path)
        except (OSError, UnicodeDecodeError) as exc:
            raise ConfigError(
                "cannot read included file {}: {}".format(inc_path, exc)
            )
        out.extend(_expand(inc_path, inc_lines, stack + (real,)))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file.
    """
    lines = _read_lines(path)
    lines = _expand(path, lines, (os.path.realpath(path),))
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
